def advantageCount(nums1: list[int], nums2: list[int]) -> list[int]:
    from collections import deque
    sorted1 = deque(sorted(nums1))
    order2 = sorted(range(len(nums2)), key=lambda x: nums2[x])
    res = [0] * len(nums1)
    for idx in order2:
        if sorted1[-1] > nums2[idx]:
            # find smallest in sorted1 > nums2[idx]
            for i in range(len(sorted1)):
                if sorted1[i] > nums2[idx]:
                    res[idx] = sorted1[i]
                    del sorted1[i]
                    break
        else:
            res[idx] = sorted1.popleft()
    return res

